// OnConflict allows configuring the `ON CONFLICT` / `ON DUPLICATE KEY` clause
// of the `INSERT` statement. For example:
//
//	client.Contest.Create().
//		SetCreatedAt(v).
//		OnConflict(
//			// Update the row with the new values
//			// the was proposed for insertion.
//			sql.ResolveWithNewValues(),
//		).
//		// Override some of the fields with custom
//		// update values.
//		Update(func(u *ent.ContestUpsert) {
//			SetCreatedAt(v+v).
//		}).
//		Exec(ctx)
func (_c *ContestCreate) OnConflict(opts ...sql.ConflictOption) *ContestUpsertOne {
	_c.conflict = opts
	return &ContestUpsertOne{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
// as conflict target. Using this option is equivalent to using:
//
//	client.Contest.Create().
//		OnConflict(sql.ConflictColumns(columns...)).
//		Exec(ctx)
func (_c *ContestCreate) OnConflictColumns(columns ...string) *ContestUpsertOne {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &ContestUpsertOne{
		create: _c,
	}
}

type (
	// ContestUpsertOne is the builder for "upsert"-ing
	//  one Contest node.
	ContestUpsertOne struct {
		create *ContestCreate
	}

	// ContestUpsert is the "OnConflict" setter.
	ContestUpsert struct {
		*sql.UpdateSet
	}
)

